using LocalChat;
using System.IO.Compression;
using System.Text;
int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);passed++;Console.WriteLine("PASS "+name);}
var tmp=Path.Combine(Path.GetTempPath(),"nora-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(tmp);
try{
 var chat=new ChatSession{Title="Проверка автосохранения",Draft="Черновик",Attachments=new(){new(){Name="test.md",Text="Файл"}}};chat.Messages.Add(new(){Role="user",Text="Привет"});chat.Messages.Add(new(){Role="assistant",Text="Привет, Вась!"});var path=Path.Combine(tmp,"chats",chat.Id+".json");Disk.Save(path,chat);var loaded=Disk.Read<ChatSession>(path)!;Check(loaded.Title==chat.Title&&loaded.Draft=="Черновик"&&loaded.Messages[1].Text=="Привет, Вась!","save and reload chat Unicode");Check(loaded.Attachments[0].Text=="Файл","attachments persisted");chat.Messages[1].Text="Новая версия";Disk.Save(path,chat);Check(Disk.Read<ChatSession>(path)!.Messages[1].Text=="Новая версия"&&!File.Exists(path+".tmp"),"atomic replace");
 Check(Disk.History(chat).Count==2,"complete pair included");chat.Messages.Add(new(){Role="user",Text="Отмени"});chat.Messages.Add(new(){Role="assistant",Text="обрыв",State="cancelled"});Check(Disk.History(chat).Count==2,"cancelled pair excluded");chat.Messages.Add(new(){Role="user",Text="ошибка"});chat.Messages.Add(new(){Role="assistant",Text="error",State="error"});Check(Disk.History(chat).Count==2,"error pair excluded");
 foreach(var id in new[]{"../../other","x",new string('g',32)}){bool refused=false;try{Disk.Id(id);}catch(ArgumentException){refused=true;}Check(refused,"unsafe id refused");}Check(Disk.Id(chat.Id)==chat.Id,"valid id allowed");
 Check(GitHubImport.Parse("https://github.com/msitarzewski/agency-agents")==("msitarzewski","agency-agents"),"github root accepted");Check(GitHubImport.Parse("https://github.com/test/repo.git")==("test","repo"),"git suffix normalized");
 foreach(var u in new[]{"http://github.com/a/b","https://evil.com/a/b","https://github.com/a/b/tree/main","https://github.com/a/b?token=secret","https://user:pass@github.com/a/b"}){bool refused=false;try{GitHubImport.Parse(u);}catch(ArgumentException){refused=true;}Check(refused,"unsafe repo URL refused");}
 using(var buffer=new MemoryStream()){using(var z=new ZipArchive(buffer,ZipArchiveMode.Create,true))foreach(var(n,t)in new[]{("project/README.md","Hello repo"),("project/AGENTS.md","Role instructions"),("project/src/auth.py","def login(): return 'safe'"),("project/../escape.md","bad"),("/absolute/bad.md","bad"),("project/.env","SECRET"),("project/node_modules/pkg/main.js","ignored"),("project/photo.png","fake")}){using var writer=new StreamWriter(z.CreateEntry(n).Open());writer.Write(t);}buffer.Position=0;var repo=GitHubImport.ReadZip(buffer);Check(repo.Files.Count==3,"zip only eligible files");Check(repo.Files[0].Path=="AGENTS.md","agent instructions prioritized");Check(repo.Files.All(f=>!f.Path.Contains("..")&&!f.Text.Contains("SECRET")),"zip traversal and secrets excluded");var ctx=GitHubImport.Context(repo,"login auth",500);Check(ctx.text.Contains("login")&&ctx.paths.Contains("src/auth.py"),"relevant context selected");Check(ctx.text.Length<600,"context bounded");}
 string textPath=Path.Combine(tmp,"input.md");File.WriteAllText(textPath,"Привет, мир!");Check(FileTools.ReadText(textPath)=="Привет, мир!","UTF8 text read");string binary=Path.Combine(tmp,"bad.txt");File.WriteAllBytes(binary,new byte[]{0,1,2});bool binaryRejected=false;try{FileTools.ReadText(binary);}catch{binaryRejected=true;}Check(binaryRejected,"binary rejected");
 string docx=Path.Combine(tmp,"input.docx");using(var z=ZipFile.Open(docx,ZipArchiveMode.Create)){using var writer=new StreamWriter(z.CreateEntry("word/document.xml").Open());writer.Write("<doc><p><t>Тест документа</t></p></doc>");}Check(FileTools.ReadText(docx).Contains("Тест документа"),"DOCX text extracted");
 string zipPath=Path.Combine(tmp,"answer.zip");FileTools.WriteZip(zipPath,"Ответ\n```python\nprint('hello')\n```\n```html\n<h1>Test</h1>\n```");using(var z=ZipFile.OpenRead(zipPath)){Check(z.Entries.Select(e=>e.FullName).SequenceEqual(new[]{"answer.md","code-01.py","code-02.html"}),"ZIP artifacts include code");Check(z.Entries.All(e=>!e.FullName.Contains("/")),"generated names cannot traverse");}
 Check(Profiles.BuiltIn().Select(p=>p.Id).Distinct().Count()==5,"five distinct local agent profiles");Check(Profiles.BuiltIn().Any(p=>p.Id=="security"),"security profile exists");
 string pdf=Path.Combine(AppContext.BaseDirectory,"fixture.pdf");Check(File.Exists(pdf),"PDF fixture included");Check(FileTools.ReadText(pdf).Contains("NORA PDF test"),"PDF text extracted");
 if(Environment.GetEnvironmentVariable("NORA_LIVE_TEST")=="1"){using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(3));var repo=await GitHubImport.Download("https://github.com/msitarzewski/agency-agents",timeout.Token);Check(repo.Files.Count>10,"live Agency Agents import");Check(repo.Files.Any(f=>f.Path.Contains("design",StringComparison.OrdinalIgnoreCase)),"live design profiles available");foreach(var key in new[]{"ui-designer","frontend-developer","ai-generated-code-auditor"}){var f=repo.Files.FirstOrDefault(f=>(f.Path.Contains(key,StringComparison.OrdinalIgnoreCase)||(key=="ai-generated-code-auditor"&&f.Path.StartsWith("security/",StringComparison.OrdinalIgnoreCase)))&&f.Text.Length<=20000);Check(f!=null&&f.Text.Length<=20000,"installable Agency profile "+key);if(key=="ai-generated-code-auditor")Check(f!.Path=="security/security-ai-generated-code-auditor.md","real security role selected, not repository policy");Console.WriteLine(f?.Path+" chars="+f?.Text.Length);}Console.WriteLine("Imported "+repo.Files.Count+" text files; scripts not executed.");}
 foreach(var ip in new[]{"127.0.0.1","10.0.0.1","192.168.1.1","172.16.0.1","169.254.169.254","::1","fe80::1","fc00::1","100.64.0.1","::ffff:127.0.0.1"})Check(!WebReader.Public(System.Net.IPAddress.Parse(ip)),"private address denied "+ip);
 Check(WebReader.Public(System.Net.IPAddress.Parse("1.1.1.1")),"public address allowed");
 foreach(var url in new[]{"file:///etc/passwd","http://example.com","https://user:pass@example.com","https://example.com:8443"}){bool denied=false;try{WebReader.Parse(url);}catch{denied=true;}Check(denied,"unsafe web URL denied");}
 if(Environment.GetEnvironmentVariable("NORA_LIVE_TEST")=="1"){using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(40));var page=await WebReader.Read("https://example.com/",timeout.Token);Check(page.text.Contains("Example Domain"),"live public page text read");bool blocked=false;try{await WebReader.Read("https://127.0.0.1/",timeout.Token);}catch{blocked=true;}Check(blocked,"live loopback webpage blocked before network");}
 Console.WriteLine($"{passed} core checks passed");
}finally{Directory.Delete(tmp,true);}
